import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = data[2:2 + r]
    low = max(i for i in range(r) if '*' in g[i])
    d = r - 1 - low
    total = 0
    for j in range(c):
        covered = -1
        for i in range(r):
            if g[i][j] == '*':
                lo = max(i + 1, covered + 1)
                hi = i + d
                for k in range(lo, hi + 1):
                    if g[k][j] == '#':
                        total += 1
                if hi > covered:
                    covered = hi
    print(total)

