def gen(rng):
    def fmt(rows):
        return f'{len(rows)} {len(rows[0])}\n' + '\n'.join(rows)
    def grid(r, c, ps, ph, srows=None):
        rows = []
        for i in range(r):
            row = []
            for j in range(c):
                x = rng.random()
                if (srows is None or i < srows) and x < ps:
                    row.append('*')
                elif x < ps + ph:
                    row.append('#')
                else:
                    row.append('.')
            rows.append(row)
        if not any('*' in row for row in rows):
            rows[rng.randrange(srows or r)][rng.randrange(c)] = '*'
        return [''.join(row) for row in rows]
    tests = [
        fmt(['*.', '#.']),
        fmt(['*#', '#.']),
        fmt(['.*', '**']),
        fmt(['*.#', '#*.', '.#.', '###']),
        fmt(['#*#', '#.#', '#.#', '#.#', '#.#']),
        fmt(['*' * 5, '#' * 5, '#' * 5, '#' * 5]),
    ]
    for _ in range(14):
        r, c = rng.randint(2, 9), rng.randint(2, 9)
        tests.append(fmt(grid(r, c, rng.choice([0.05, 0.15, 0.3]), rng.choice([0.2, 0.4, 0.6]))))
    for _ in range(4):
        r, c = rng.randint(6, 10), rng.randint(2, 8)
        tests.append(fmt(grid(r, c, 0.3, 0.5, srows=3)))
    tests.append(fmt(grid(99, 99, 0.02, 0.5)))
    tests.append(fmt(grid(99, 99, 0.05, 0.9, srows=10)))
    tests.append(fmt(grid(99, 99, 0.3, 0.3, srows=4)))
    tests.append(fmt(['*' * 99] + ['#' * 99] * 98))
    return tests

